use super::*;

/// Restart the device's unit, when it has one. A device with no `service` needs nothing restarted, so
/// this is a no-op rather than an error.
pub fn restart(device: &Device) -> Result<(), String> {
    let Some(unit) = &device.service else { return Ok(()) };
    ssh(device, &format!("sudo systemctl restart {unit}")).map(|_| ())
}
